// If true, a failure to read a message from offline storage will
// discard it, to allow subsequent automatic reloading (self-healing).
pref("mail.discard_offline_msg_on_failure", true);

NS_IMETHOD OnStopRequest(nsIRequest* request, nsresult status) override {
  AUTO_PROFILER_LABEL("ImapOfflineMsgStreamListener::OnStopRequest",
                      MAILNEWS);
  MOZ_RELEASE_ASSERT(NS_IsMainThread());
  nsresult rv = mListener->OnStopRequest(mChannel, status);
  mListener = nullptr;
  mChannel->Close();
  mChannel = nullptr;
  if (NS_FAILED(status) &&
      Preferences::GetBool("mail.discard_offline_msg_on_failure", true)) {
    // The streaming failed, discard the offline copy of the message.
    mFolder->DiscardOfflineMsg(mMsgKey);
  }
  return rv;

NS_IMETHODIMP OfflineMessageReadListener::OnStopRequest(nsIRequest* request,
                                                        nsresult status) {
  nsresult rv = mDestination->OnStopRequest(mChannel, status);
  if (NS_FAILED(status) &&
      Preferences::GetBool("mail.discard_offline_msg_on_failure", true)) {
    // The streaming failed, discard the offline copy of the message so it can
    // be downloaded again later.
    mFolder->DiscardOfflineMsg(mMsgKey);
  }
  // We no longer need the channel. Clean it up so both it and this listener can
  // be collected.
  mChannel = nullptr;
  return rv;

NS_IMETHODIMP nsMsgDBFolder::DiscardOfflineMsg(nsMsgKey msgKey) {
  GetDatabase();
  if (!mDatabase) return NS_ERROR_FAILURE;

  nsresult rv;
  RefPtr<nsIMsgDBHdr> hdr;
  rv = mDatabase->GetMsgHdrForKey(msgKey, getter_AddRefs(hdr));
  if (NS_FAILED(rv)) return rv;
  if (!hdr) {
    return NS_ERROR_FAILURE;
  }
